<?php
require __DIR__.'/config.php';$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$u=$q->fetch();if(!$u){http_response_code(404);exit('Member not found.');}db()->prepare('UPDATE users SET views=views+1 WHERE id=?')->execute([$id]);$st=db()->prepare('SELECT * FROM videos WHERE user_id=? ORDER BY created_at DESC');$st->execute([$id]);$videos=$st->fetchAll();require __DIR__.'/includes/header.php';?>
<div class="listing"><h2><?=h($u['username'])?></h2><p class="center">Member since <?=h(fmt_date($u['created_at']))?> · Views: <?=number_format($u['views']+1)?></p><h3>Videos by <?=h($u['username'])?></h3><div class="video-grid"><?php foreach($videos as $v):?><div class="video-cell"><a href="watch.php?id=<?=$v['id']?>"><img class="video-thumb" src="<?=h(video_thumb($v))?>" alt=""><?=h($v['title'])?></a><br><span class="red">Views: <?=number_format($v['views'])?></span></div><?php endforeach;?><?php if(!$videos):?><p class="empty">This member has not uploaded videos yet.</p><?php endif;?></div></div>
<?php require __DIR__.'/includes/footer.php';?>
